{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "Parents of participating students would be required to ensure their children take all annual Tennessee comprehensive assessment program (TCAP) tests (or state-authorized successor tests) required for their grade or course. Students in grade 11 must take the examination required for public school students in that grade, and students in kindergarten through grade three must annually take three approved universal reading screeners during established windows. Students with disabilities who use alternate assessments as determined by their IEP are exempt.",
      "rationale": "Conveys parental responsibility, annual grade- or course-specific TCAP testing or authorized successors, and the IEP-based alternate-assessment exemption."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Parents of participating students would be required to ensure their children take all annual Tennessee comprehensive assessment program (TCAP) tests (or state-authorized successor tests) required for their grade or course. Students in grade 11 must take the examination required for public school students in that grade, and students in kindergarten through grade three must annually take three approved universal reading screeners during established windows. Students with disabilities who use alternate assessments as determined by their IEP are exempt.",
      "rationale": "In the context of the parental testing requirements, identifies the same examination required for public school eleventh graders and includes the alternate-assessment exemption."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "Students in grade 11 must take the examination required for public school students in that grade, and students in kindergarten through grade three must annually take three approved universal reading screeners during established windows.",
      "rationale": "Conveys annual K–3 screening, but does not specify administration during each of three department-established windows or identify the Tennessee screeners and state-board-approved alternatives."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Test results must be reported to the student's parent.",
      "rationale": "Expressly conveys the requirement to report the participating student's test results to the parent."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "Students with disabilities who use alternate assessments as determined by their IEP are exempt.",
      "rationale": "Conveys the exemption for students with disabilities whose IEP determines alternate-assessment participation."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Participating schools would be required to publish their lesson plans, syllabi, academic standards for every class, and a current list of library materials on the school's website.",
      "rationale": "Includes the participating-school actor, website publication, all required categories, every-class scope, and a current library-materials list."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "For these purposes, library materials include items like books, films, video games, and subscription content provided to students.",
      "rationale": "Conveys that the definition covers varied materials provided to students, but omits the explicit inclusion of course-curriculum materials and the full range of covered formats."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "Additionally, participating schools must ensure all their educators hold a valid public school teaching license issued by the state board of education.",
      "rationale": "Conveys the school's duty, coverage of all educators, license validity, public-school teaching qualification, and issuing authority."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "Participating schools would be required to publish their lesson plans, syllabi, academic standards for every class, and a current list of library materials on the school's website.",
      "rationale": "The consolidated description conveys the parallel website-publication requirement, including each required category and its scope."
    },
    {
      "proposition_id": "P10",
      "status": "partial",
      "summary_quote": "For these purposes, library materials include items like books, films, video games, and subscription content provided to students.",
      "rationale": "Partly conveys the parallel definition, but omits express coverage of course-curriculum materials and the full range of covered formats."
    },
    {
      "proposition_id": "P11",
      "status": "full",
      "summary_quote": "Additionally, participating schools must ensure all their educators hold a valid public school teaching license issued by the state board of education.",
      "rationale": "The consolidated statement conveys the parallel licensing requirement for all participating-school educators."
    },
    {
      "proposition_id": "P12",
      "status": "partial",
      "summary_quote": "Parents of participating students would be required to ensure their children take all annual Tennessee comprehensive assessment program (TCAP) tests (or state-authorized successor tests) required for their grade or course.",
      "rationale": "Describes the corresponding annual testing requirement, but frames it as a parental duty rather than separately identifying testing as a condition of program participation."
    },
    {
      "proposition_id": "P13",
      "status": "partial",
      "summary_quote": "Students in grade 11 must take the examination required for public school students in that grade",
      "rationale": "Identifies the required eleventh-grade examination, but omits its status as a condition of program participation."
    },
    {
      "proposition_id": "P14",
      "status": "partial",
      "summary_quote": "students in kindergarten through grade three must annually take three approved universal reading screeners during established windows.",
      "rationale": "Conveys annual K–3 screening, but omits the participation condition, administration during each of three department-established windows, and the specified Tennessee or state-board-approved screeners."
    },
    {
      "proposition_id": "P15",
      "status": "full",
      "summary_quote": "The bill would take effect on July 1, 2025.",
      "rationale": "States the exact effective date."
    }
  ]
}
